"""生成 PRD §5.4 验收所需的 3 本真实中文 TXT 样本（可重复执行）。

运行：python tests/fixtures/generate.py
输出：utf8-novel.txt / utf8-bom.txt / gbk-novel.txt
"""

from pathlib import Path

OUT = Path(__file__).resolve().parent

UTF8_NOVEL = """　　第一章　山雨欲来

　　清晨的雾气还没散，青石镇的老街已经醒了。卖豆浆的支起摊子，木勺碰着铁锅，叮当一声，像给这一天开了个头。林砚背着半旧的书箱，从巷口走过来，走得慢，不是因为累，是怕惊扰了这份安静。

　　街尾的茶馆二楼，有人推开窗往外看了一眼。那人穿一身靛青长衫，手里捏着半盏凉茶，目光落在林砚身上，停了很久。「来了。」他轻声说，声音低得连自己都几乎没听见。

　　没有人应他。楼下传来一阵马蹄声，由远及近，又渐渐远了。雾气里，只有那盏凉茶还冒着极淡的热气，风一吹就散了。

　　第二章　旧信

　　信是三天前到的，信封上没有落款，只写了两个字：速归。林砚把信折好，压在书箱最底下，一路上没再打开过。他心里清楚，有些事躲不开，早一天晚一天，总归要回去面对。

　　巷子尽头的石桥上，一个小孩正蹲着数蚂蚁。林砚从他身边走过，忽然想起很多年前，自己也这样蹲过，那时候母亲还在，天总是很蓝。
"""

# 无空行的硬换行长文：每行约 30 字，句子跨行，用于验证启发式合并（不能一行一段）。
HARD_WRAP_LINES = [
    "　　城南的旧书店开在一条窄巷里，门脸不大，招牌上的字被雨水洗得发白，只剩一个「书」字还看得出笔画。老板姓陈，五十来岁，常年穿一件洗到发灰的布衫，见人先笑，话却不多。",
    "　　那天下午下着小雨，我躲进去避雨，顺手从架上抽出一本没有封面的旧书。纸页发黄，边角卷起，翻到第三页时，一行铅笔小字忽然撞进眼里：若你读到这里，请替我看看那年冬天。",
    "　　我抬头找陈老板，他正拿抹布擦柜台，动作慢得像在数日子。我问这书从哪来的，他说是收旧货时一并称回来的，按斤算，不值几个钱，也就没人细看里面写了什么。",
    "　　雨停的时候我把书买下了。走出巷口回头望，灯已经亮起来，昏黄的一小团，贴在湿漉漉的青石板上。后来我常常想起那行铅笔字，想起一个不认得的人，把话留在了书里。",
    "　　第二年冬天我搬了家，书箱压在衣柜顶上，一放就是好久。再翻出来时，纸页更脆了，那行字却还在，笔画淡淡的，像写字的人当时也没打算让谁一定看见。",
]

GBK_NOVEL_LINES = [
    "第一章　旧书店",
    "　　城南的旧书店开在一条窄巷里，门脸不大，招牌上的字被雨水洗得发白。老板姓陈，五十来岁，常年穿一件洗到发灰的布衫，见人先笑，话却不多。",
    "　　那天下午下着小雨，我躲进去避雨，顺手从架上抽出一本没有封面的旧书。纸页发黄，边角卷起，翻到第三页时，一行铅笔小字忽然撞进眼里。",
    "　　我抬头找陈老板，他正拿抹布擦柜台，动作慢得像在数日子。我问这书从哪来的，他说是收旧货时一并称回来的，按斤算，不值几个钱。",
    "　　雨停的时候我把书买下了。走出巷口回头望，灯已经亮起来，昏黄的一小团，贴在湿漉漉的青石板上，像是给这条巷子留了个小小的注脚。",
    "第二章　雪夜来客",
    "　　腊月里第一场雪落下来时，店门被风推开一条缝。来人抖了抖肩上的雪，没说话，只把一本用蓝布包着的书放在柜台上，转身就走了。",
    "　　陈老板解开布包，愣了很久。那是他年轻时抄过的一册旧诗，扉页上还留着自己的字迹，只是纸边多了一圈水痕，像被谁反复翻过许多遍。",
]


def hard_wrap(paragraph: str, width: int = 32) -> list[str]:
    """模拟中文 TXT 常见的硬换行：句子跨行，仅段落首行带全角空格缩进。"""
    body = paragraph.strip()
    lines = [body[i : i + width] for i in range(0, len(body), width)]
    if lines:
        lines[0] = "\u3000\u3000" + lines[0]
    return lines


def expand(paragraphs: list[str]) -> str:
    out: list[str] = []
    for paragraph in paragraphs:
        out.extend(hard_wrap(paragraph))
    return "\n".join(out) + "\n"


def main() -> None:
    (OUT / "utf8-novel.txt").write_text(UTF8_NOVEL, encoding="utf-8", newline="\n")
    (OUT / "utf8-bom.txt").write_text(
        expand(HARD_WRAP_LINES), encoding="utf-8-sig", newline="\n"
    )
    (OUT / "gbk-novel.txt").write_text(
        expand(GBK_NOVEL_LINES), encoding="gbk", newline="\n"
    )
    for name in ("utf8-novel.txt", "utf8-bom.txt", "gbk-novel.txt"):
        path = OUT / name
        print(f"{name}: {path.stat().st_size} bytes")


if __name__ == "__main__":
    main()
